import zipfile, xml.etree.ElementTree as ET
from pathlib import Path

def docx_text(p):
  with zipfile.ZipFile(p) as z:
    xml=z.read('word/document.xml')
  root=ET.fromstring(xml)
  t=' '.join([e.text for e in root.iter() if e.tag.endswith('}t') and e.text])
  return t

def pptx_text(p):
  out=[]
  with zipfile.ZipFile(p) as z:
    slides=sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')])
    for n in slides[:2]:
      root=ET.fromstring(z.read(n))
      out += [e.text for e in root.iter() if e.tag.endswith('}t') and e.text]
  return ' '.join(out)

base=Path('/root/papers/all')
for fn in ['paper_file_1.docx','paper_file_2.docx','DAMOP.pptx']:
  p=base/fn
  print('====', fn)
  if fn.endswith('.docx'):
    print(docx_text(p)[:800])
  else:
    print(pptx_text(p)[:800])
